{"cmd": "python3 -c "
import json, os
results_dir = '/opt/public_eval/results'
for f in sorted(os.listdir(results_dir)):
    if f.endswith('.json'):
        with open(os.path.join(results_dir, f)) as fp:
            d = json.load(fp)
        method_hash = f[:-5]
        # Get summary stats
        print(f'=== {method_hash[:12]} ===')
        if 'aggregate' in d:
            print(f'  Aggregate time: {d[\"aggregate\"]:.4f}s')
        if 'score' in d:
            print(f'  Score: {d[\"score\"]:.4f}')
        if 'valid' in d:
            print(f'  Valid: {d[\"valid\"]}')
        # Check per-case quality
        cases = d.get('cases', {})
        worst_nrmse = 0
        worst_spearman = 1
        worst_overlap = 1
        for cname, cdata in cases.items():
            if 'nrmse' in cdata: worst_nrmse = max(worst_nrmse, cdata['nrmse'])
            if 'spearman' in cdata: worst_spearman = min(worst_spearman, cdata['spearman'])
            if 'top_quartile_overlap' in cdata: worst_overlap = min(worst_overlap, cdata['top_quartile_overlap'])
        print(f'  Worst NRMSE: {worst_nrmse:.6f}')
        print(f'  Worst Spearman: {worst_spearman:.6f}')
        print(f'  Worst overlap: {worst_overlap:.6f}')
        print()
"", "max_output_tokens": 3000}

