            print(f'  Score: {d[\"score\"]:.4f}')
        if 'valid' in d:
            print(f'  Valid: {d[\"valid\"]}')
        if 'cases' in d:
            cases = d['cases']
            print(f'  Num cases: {len(cases)}')
            if isinstance(cases, list) and len(cases) > 0:
                print(f'  First case keys: {list(cases[0].keys())}')
                print(f'  First case: {cases[0]}')
        break
